def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    marker = max((v for v in counts if v != bg), key=lambda v: counts[v])

    # The small colored object is a stamp; its background-colored cells
    # inside its bounding box are part of the stamp as well.
    pts = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] not in (bg, marker)]
    if not pts:
        return [row[:] for row in grid]

    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    cr, cc = (r0 + r1) // 2, (c0 + c1) // 2
    stamp = [(r - cr, c - cc, grid[r][c])
             for r in range(r0, r1 + 1)
             for c in range(c0, c1 + 1)]

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                for dr, dc, color in stamp:
                    rr, col = r + dr, c + dc
                    if 0 <= rr < h and 0 <= col < w:
                        out[rr][col] = color
    return out
